mapper.select:
SELECT id,trade_date,universe_scope,source,content_hash,metrics_json, CASE WHEN #{loadRaw} THEN raw_json ELSE NULL END AS raw_json,fetched_at FROM market_breadth_snapshot WHERE id=( SELECT MAX(id) FROM market_breadth_snapshot WHERE trade_date=#{date} AND universe_scope='FULL_A' AND source=#{source}
AND JSON_TYPE(JSON_EXTRACT(raw_json, '$.rosterEvidence.rosterSources')) = 'OBJECT'
AND JSON_TYPE(JSON_EXTRACT(raw_json, '$.rosterEvidence.comparison')) = 'OBJECT'
)
